data.mutation:
mutation upsertContact(
  $contacts:[ContactUpsertPayloadInput!]!,
  $customerContacts:[CustomerContactUpsertPayloadInput!]!,
  $supplierContacts:[SupplierContactUpsertPayloadInput!]!
){
  upsertContact(payload:$contacts) {
    id
  }
  upsertCustomerContact(payload:$customerContacts) {
    id
  }
  upsertSupplierContact(payload:$supplierContacts) {
    id
  }
}

