mutation ($workcenter: [WorkcenterUpsertPayloadInput!]!)  {
  data: upsertWorkcenter(payload: $workcenter) {
    id
    code
    maximumPositions
    maximumConcurrency
  }
}

data.variablesTransform:
(
  $workcenters := [data];

  $toWorkcenterPositions := function($workcenterId,$workcenterCode,$maximumPositions,$maximumConcurrency){
    (
      $maxPositions := ($maximumPositions * $maximumConcurrency);

      ([1..$maxPositions])#$i.(
        {
          "id": $join([$workcenterId,$string($i+1)],'::'), 
          "name": $join([$workcenterCode,$string($i+1)],'::'), 
          "workcenterId": $workcenterId,
          "number": $string($i+1)
        }
      );
    )
  };

  {     
    "workcenterPosition": [
      $workcenters.(
        $payload := $toWorkcenterPositions(id,code,maximumPositions,maximumConcurrency);
        $payload.{
           "where": {
             "id": id
            },
           "create": {
             "id": id,
             "name": name,
             "workcenterId": workcenterId,
             "number": number
            },
           "update": {
             "name": name,
             "workcenterId": workcenterId,
             "number": number
          }
        }
      )
    ]
  }
)

